# -*- coding: utf-8 -*-
"""Переводы действий (не атак), легендарных действий и реакций монстров SRD 5.1."""
import re
from ru_traits import DT, AB

BREATH_WHAT = {'acid': 'кислоту', 'fire': 'огонь', 'cold': 'ледяной вихрь', 'lightning': 'молнию', 'poison': 'ядовитый газ'}


def area_phrase(desc):
    ln = re.search(r'(\d+)-?\s?foot line that is (\d+) f(?:ee|oo)t wide', desc) or re.search(r'line that is (\d+) ft\. long and (\d+) ft\. wide', desc)
    if ln:
        return ('line', int(ln.group(1)), int(ln.group(2)), 'линией длиной %s фт. и шириной %s фт.' % (ln.group(1), ln.group(2)))
    cn = re.search(r'(\d+)-?\s?foot cone', desc)
    if cn:
        return ('cone', int(cn.group(1)), 0, '%s-футовым конусом' % cn.group(1))
    return None


def breath_text(desc):
    """Перевод одного варианта оружия дыхания."""
    ar = area_phrase(desc)
    shape = ar[3] if ar else ''
    sv = re.search(r'DC (\d+) (\w+) saving throw', desc)
    dm = re.search(r'(\d+) \((\d+d\d+(?: ?[+-] ?\d+)?)\) (\w+) damage', desc)
    if dm:
        what = BREATH_WHAT.get(dm.group(3), 'энергию')
        s = 'Выдыхает %s %s. Каждое существо в области совершает спасбросок %s со Сл %s, получая %s (%s) %s при провале' % (
            what, shape, AB[sv.group(2)], sv.group(1), dm.group(1), dm.group(2), DT[dm.group(3)])
        return s + (' или половину при успехе.' if 'half' in desc else '.')
    if 'sleep' in desc:
        return 'Выдыхает усыпляющий газ %s. Каждое существо в области должно преуспеть в спасброске %s со Сл %s, иначе потеряет сознание на %s мин. Эффект оканчивается, если существо получает урон или кто-то будит его действием.' % (
            shape, AB[sv.group(2)], sv.group(1), re.search(r'for (\d+) minute', desc).group(1))
    if 'repulsion' in desc:
        return 'Выдыхает отталкивающую энергию %s. Каждое существо в области должно преуспеть в спасброске Силы со Сл %s, иначе отталкивается на %s фт.' % (
            shape, sv.group(1), re.search(r'pushed (\d+)', desc).group(1))
    if 'Slowing' in desc or "can't use reactions" in desc:
        return 'Выдыхает замедляющий газ %s. Каждое существо в области совершает спасбросок Телосложения со Сл %s. При провале на 1 минуту не может совершать реакции, его скорость уменьшается вдвое, оно совершает не более одной атаки за ход и только действие или бонусное действие. Повтор спасброска в конце каждого хода.' % (shape, sv.group(1))
    if 'disadvantage on Strength' in desc:
        return 'Выдыхает ослабляющий газ %s. Каждое существо в области должно преуспеть в спасброске Силы со Сл %s, иначе на 1 минуту совершает с помехой атаки, проверки и спасброски, основанные на Силе. Повтор спасброска в конце каждого хода.' % (shape, sv.group(1))
    if 'paralyz' in desc:
        return 'Выдыхает парализующий газ %s. Каждое существо в области должно преуспеть в спасброске Телосложения со Сл %s, иначе будет парализовано на 1 минуту. Повтор спасброска в конце каждого хода.' % (shape, sv.group(1))
    if 'petrif' in desc:
        return 'Выдыхает окаменяющий газ %s. Каждое существо в области должно преуспеть в спасброске Телосложения со Сл %s. При провале начинает каменеть и опутано; в конце своего следующего хода повторяет спасбросок: при успехе эффект оканчивается, при провале существо окаменевает до снятия высшим восстановлением.' % (shape, sv.group(1))
    if 'blind' in desc:
        return 'Выдыхает ослепляющую пыль %s. Каждое существо в области должно преуспеть в спасброске Ловкости со Сл %s, иначе будет ослеплено на 1 минуту. Повтор спасброска в конце каждого хода.' % (shape, sv.group(1))
    return 'Выдыхает энергию %s.' % shape


def safe_format(t, n):
    return re.sub(r'\{(\d+)\}', lambda mm: str(n[int(mm.group(1))]) if int(mm.group(1)) < len(n) else '?', t)


def by_index(table):
    def f(desc, n, m):
        key = 'vampire-vampire' if m['index'].startswith('vampire') and 'vampire-vampire' in table else m['index']
        tpl = table.get(key, table['*'])
        if '?' in safe_format(tpl, n):
            print('WARN мало чисел', m['index'], tpl[:50])
        return safe_format(tpl, n)
    return f


